L07_C4_B3_05.latex:
\begin{ex}%[7H4H3]
\immini[thm]{
Cho tam giác ${PQR}$ có $PQ=PR$. Gọi ${T}$ là trung điểm của cạnh ${QR}$. Chứng minh 

a)  $\widehat{Q} = \Delta{R}$ 

b) $PT$ là phân giác của góc $\widehat{QPR}$ c) $PT \bot QR$
}{
\begin{tikzpicture}

    % Coordinates of points
    \coordinate (A) at (0,4);
    \coordinate (B) at (-2,0);
    \coordinate (C) at (2,0);
    \coordinate (M) at (0,0);

    % Draw the triangles
    \draw (A) -- (B) -- (C) -- cycle; % Triangle ABC
    \draw (A) -- (M); 


    % Labels
    \node[above] at (A) {$P$};
    \node[ left] at (B) {$Q$};
    \node[right] at (C) {$R$};
    \node[below ] at (M) {$T$};
       \filldraw [black] (A) circle (1.5pt);
    \filldraw [black] (B) circle (1.5pt);
    \filldraw [black] (C) circle (1.5pt);
    \filldraw [black] (M) circle (1.5pt);
    \draw
    ($(A)!0.5!(C)$)node[rotate=20]{$/$} ($(A)!0.5!(B)$)node[rotate=20]{$/$};
    \end{tikzpicture}
}
\loigiai{
a) $\Delta{PQT} = \Delta{PRT}$ (c.c.c) nên $\widehat{Q} = \widehat{R}$ (Hai góc tương ứng bằng nhau)\\
b) Vì $\Delta{PQT} = \Delta{PRT}$ (cmt) nên $\widehat{QPT} = \widehat{RPT}$ nên $PT$ là phân giác của góc $\widehat{QPR}$\\
c) $\widehat{PTQ} = \widehat{PTR}$ (hai góc tương ứng)\\
Mà $\widehat{PTQ} + \widehat{PTR} = 180^{\circ}$ nên $\widehat{PTQ} = \widehat{PTR} = 90^{\circ}$\\
Do đó $PT \bot QR$
}\end{ex}

