L07_C4_B5_05.latex:
\begin{ex}%[7H4H5]
\immini[thm]{
Cho $\triangle {DHK}$, vẽ điểm ${O}$ là trung điểm của ${HK}$. Trên tia đối của tia ${OD}$ lấy điểm ${L}$ sao cho ${OD = OL}$.

 a) CHứng minh $\triangle {DHO} = \triangle {LKO}$ và ${DH \parallel LK}$.

b) Kẻ ${HM \perp DO}$ (${M \in DO}$), ${KN \perp LO}$ ($N \in LO$). Chứng minh rằng ${O}$ là trung điểm của ${MN}$ \\
}{
\begin{tikzpicture}[scale=1, font=\footnotesize, line join=round, line cap=round, >=stealth]
    \def\r{2.5}

    \def\gocA{130}
    \path (0,0) coordinate (O)
    (\gocA:\r) coordinate (A)
    (210:\r) coordinate (B)
    (-30:\r) coordinate (C)
    ($(C)!0.5!(B)$) coordinate (M)
    ($(A)!2!(M)$) coordinate (D)
    ($(A)!(B)!(M)$) coordinate (E) 
    ($(A)!(C)!(M)$) coordinate (F) 
    ;
    \draw (A)--(B)--(C)--cycle (C)--(D)--(A)  (B)--(E)  (C)--(F)
    ;
    \foreach \x/\y in {M/B,M/C}{
        \draw ($(\x)!0.5!(\y)!4pt!90:(\x)$)--($(\x)!0.5!(\y)!4pt!-90:(\x)$);}
    \foreach \x/\y/\z in{B/E/A,C/F/D}
    \path pic[draw=black,angle radius = 6] {right angle = \x--\y--\z} ; 
    \filldraw[black] (A) circle (2pt) node[above left ] {$D$};
    \filldraw[black] (B) circle (2pt) node[below left] {$H$};
    \filldraw[black] (C) circle (2pt) node[above ] {$K$};
   \filldraw[black] (D) circle (2pt) node[below]{$L$};
     \filldraw[black] (E) circle (2pt) node[above right ] {$M$};
    \filldraw[black] (F) circle (2pt) node[below left] {$N$};

    \filldraw[black] (M) circle (2pt) node[above right] {$O$};

    \end{tikzpicture}
}
\loigiai{
Xét $\triangle {D H O}$ và $\triangle {L K O}$ có:\\
${O H=O K}~(gt)$\\
$\widehat{D O H}=\widehat{L O K}~(\text{đối đỉnh})$\\
${O D=O L~(gt)}$\\
Vậy $\triangle D HO=\triangle {L K O}$ (c-g-c)\\
Suy ra: $\widehat{D H O}=\widehat{L K O}$ (hai góc tương ứng).\\
Mà hai góc  ở vị trí so le trong nên ${D H\parallel L K}$\\
Xét $\triangle {HM O}$ và $\triangle {K N O}$ có:\\
$\widehat{HMO}=\widehat{KNO}=90^{\circ} $\\
${OH=OK}~(gt)$\\
$\widehat{HOM}=\widehat{KON}~(\text{đối đỉnh})$\\
Do đó: $\triangle {H M O}=\triangle {K N O}$ (cạnh huyền-góc nhọn)\\
Suy ra: ${O M=O N}$ (hai cạnh tương ứng)\\
Vậy ${O}$ là trung điểm của ${M N}$.
}\end{ex}

